// https://storybook.js.org/docs/7.0/preact/writing-stories/introduction
import type { Meta, StoryObj } from '@storybook/preact-vite';
import {
  InputDate,
  InputDateProps,
} from '@adobe-commerce/elsie/components/InputDate';
import { action } from 'storybook/actions';
import { fireEvent, userEvent, within } from 'storybook/test';

export default {
  title: 'Components/InputDate',
  component: InputDate,
  parameters: {
    layout: 'fullscreen', // centered | fullscreen
    a11y: {
      config: {
        rules: [{ id: 'color-contrast', enabled: false }],
      },
    },
  },
  args: {
    name: 'birthdate',
    label: 'Birthdate',
    error: '',
  },
  argTypes: {
    name: {
      control: 'text',
      description: 'Form field identifier.',
    },
    value: {
      control: 'text',
      description:
        'Field value in YYYY-MM-DD format. Displayed to the user in their browser locale format (e.g. MM/DD/YYYY in en-US).',
    },
    label: {
      control: 'text',
      description: 'Displayed field label.',
    },
    error: {
      control: 'text',
      description: 'Field-specific error messages.',
    },
    onChange: {
      action: 'changed',
      defaultValue: action('onChange'),
      description:
        'Function called when the value of the input changes. It is used to capture and handle the input data.',
    },
    onBlur: {
      action: 'blurred',
      defaultValue: action('onBlur'),
      description:
        'Function called when the input loses focus. This can be used to trigger validation or other effects when the user moves away from the input field.',
    },
  },
} as Meta<InputDateProps>;

const Template: StoryObj<InputDateProps> = {
  render: (args) => (
    <div style={{ margin: '40px auto', maxWidth: '1200px' }}>
      <InputDate {...args} />
    </div>
  ),
};

type Story = StoryObj<InputDateProps>;

export const Default: Story = {
  ...Template,
  args: {
    label: 'Birthdate',
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const dateInput = canvas.getByRole('textbox', { name: /date/i });
    await userEvent.click(dateInput);
    fireEvent.change(dateInput, { target: { value: '2023-07-29' } });
    await userEvent.tab();
  },
};

export const WithError: Story = {
  ...Template,
  parameters: {
    layout: 'padded',
    a11y: {
      config: {
        rules: [{ id: 'color-contrast', enabled: false }],
      },
    },
  },
  args: {
    ...Default.args,
    error: 'This field is required',
  },
};

export const CustomValue: Story = {
  ...Template,
  parameters: {
    layout: 'padded',
    a11y: {
      config: {
        rules: [{ id: 'color-contrast', enabled: false }],
      },
    },
  },
  args: {
    ...Default.args,
    value: '2023-07-29',
  },
};
